sksl:
uniform shader image;
uniform float2 size;
uniform float time;
uniform float blockSize;
uniform float aspect;
uniform float amount;
uniform float mode;
uniform float shiftPx;
uniform float rate;
uniform float seed;
uniform float opacity;
float4 tex(float2 p) {
    return float4(image.eval(clamp(p, float2(0.0), size)));
}
float3 unp(float4 c) {
    return c.rgb / max(c.a, 0.0001);
}
half4 fin(float4 o, float4 r, float op) {
    return half4(mix(o, r, saturate(op)));
}
float hash21(float2 p) {
    return fract(sin(dot(p, float2(127.1, 311.7))) * 43758.5453);
}
float2 hash22(float2 p) {
    return float2(hash21(p), hash21(p + float2(17.31, 5.17)));
}
half4 main(float2 coord) {
    float4 c = tex(coord);
    float3 s = unp(c);
    float t = floor(time * rate);
    float2 cell = floor(coord / float2(blockSize * aspect, blockSize));
    float hit = step(1.0 - amount, hash21(cell + float2(seed, t)));
    float2 r = hash22(cell + t * 7.0 + seed);
    float3 o = s;
    if (mode < 0.5) {
        o = mix(s, float3(hash21(cell + t), hash21(cell + t + 3.0), hash21(cell + t + 6.0)), hit);
    } else if (mode < 1.5) {
        o = unp(tex(coord + float2((r.x - 0.5) * 2.0 * shiftPx * hit, (r.y - 0.5) * shiftPx * 0.2 * hit)));
    } else {
        o = mix(s, 1.0 - s, hit);
    }
    return fin(c, float4(max(o, float3(0.0)) * c.a, c.a), opacity);
}
